declare specs jsonb := $all_specs$[{"signature":"world_v2.postwar_industry_run_parameter_originals(text,text,text,text)","sourcePath":"database/proposals/postwar-industry-run-parameters-read.sql","oldBodySha256":"f6f0d33f55f942e7fecb4d67814433600f695bf1b74c2cd9a249585a504d389b","newBodySha256":"858bc48d7c8dd516b3a9d03d375f95ca6e7d512ba1fe9cf1f255e21d014fabcf","owner":"world_v2_industry_source_owner","securityDefiner":true,"config":["search_path=pg_catalog"],"argumentNames":["p_world","p_country","p_seed","p_admission"],"strict":false,"volatility":"v","parallel":"u","result":"jsonb","acl":[{"grantee":"world_v2_industry_source_owner","grantor":"world_v2_industry_source_owner","privilege":"EXECUTE","grantable":false},{"grantee":"world_v2_postwar_projection_owner","grantor":"world_v2_industry_source_owner","privilege":"EXECUTE","grantable":false}],"newBody":"\ndeclare result jsonb;begin\n perform set_config('econmind.industry_source_world',p_world,true);\n select jsonb_agg(jsonb_build_object('schemaVersion','postwar-industry-run-parameter-row-v2','countryId',s.country_id,'facilityId',s.facility_id,'locationId',s.source_text::jsonb->>'locationId','operatorId',s.source_text::jsonb->>'operatorId','sourceRef',s.source_ref,'sourceRawSha256',s.source_sha256,'policyVersion',s.policy_version,'policyRawSha256',s.policy_raw_sha256,'userAdoptionRawSha256',s.user_adoption_raw_sha256,'outputUnit',s.source_text::jsonb->'recipe'->>'outputUnit','capacityPerSimDay',s.source_text::jsonb->'sourceFacility'->>'capacity','expenseCurrency',d.asset_account->>'currency','windowStartsAtSimTime',s.source_text::jsonb->>'openingWindowStartsAtSimTime','windowEndsAtSimTime',s.source_text::jsonb->>'openingWindowEndsAtSimTime','maximumMinutesPerWorkerFirstSimDay',s.source_text::jsonb->>'maximumMinutesPerWorkerFirstSimDay','measurement','ADOPTED_PARAMETERS_NOT_RUN_WORK_PAYMENT_OR_OUTPUT_AUTHORITY')order by s.facility_id collate\"C\")into result\n from world_v2.postwar_industry_first_day_source s\n join world_v2.postwar_industry_original o on o.world_id=s.world_id and o.registration_ref=s.registration_ref and o.country_id=s.country_id and o.facility_id=s.facility_id and o.seed_fingerprint=s.seed_fingerprint and o.admission_ref=s.admission_ref and o.document_sha256=s.source_text::jsonb->>'siteDocumentSha256'and o.document_sha256=encode(sha256(convert_to(o.document_text,'UTF8')),'hex')\n join world_v2.postwar_industry_deposit_original d on d.world_id=s.world_id and d.country_id=s.country_id and d.kind='OPERATOR_BANK_DEPOSIT'and d.seed_fingerprint=s.seed_fingerprint and d.admission_ref=s.admission_ref and d.asset_account->>'ownerId'=s.source_text::jsonb->>'operatorId'and d.asset_account->>'currency'=d.liability_account->>'currency'\n where s.world_id=p_world and s.country_id=p_country and s.seed_fingerprint=p_seed and s.admission_ref=p_admission\n and exists(select 1 from world_v2.runtime_opening_admission a where a.world_id=p_world and a.seed_id=s.seed_id and a.seed_fingerprint=p_seed and a.admission_ref=p_admission) and s.source_text::jsonb->>'seedId'=s.seed_id\n and s.source_sha256=encode(sha256(convert_to(s.source_text,'UTF8')),'hex')and s.source_ref='INDUSTRY_FIRST_DAY_'||upper(s.source_sha256)\n and s.source_text::jsonb->>'worldId'=p_world and s.source_text::jsonb->>'countryId'=p_country and s.source_text::jsonb->>'facilityId'=s.facility_id and s.source_text::jsonb->>'seedFingerprint'=p_seed and s.source_text::jsonb->>'admissionRef'=p_admission\n and s.source_text::jsonb->>'policyVersion'=s.policy_version and s.source_text::jsonb->>'policyRawSha256'=s.policy_raw_sha256 and s.source_text::jsonb->>'userAdoptionRawSha256'=s.user_adoption_raw_sha256\n and not exists(select 1 from world_v2.postwar_industry_first_day_source_revocation v where v.world_id=p_world and v.source_ref=s.source_ref)\n and not exists(select 1 from world_v2.postwar_industry_original_revocation v where v.world_id=p_world and v.registration_ref=s.registration_ref);\n return result;\nend;"},{"signature":"world_v2.read_postwar_industry_run_parameters_page(text,integer,integer,text)","sourcePath":"database/proposals/postwar-industry-run-parameters-read.sql","oldBodySha256":"d9daefb8be11f88c4cb3585491502445081b7cc3beb1aedb19fad414d2c62ff1","newBodySha256":"cda9dc098c7ea6445ea05cfd98a63fd7963d878e359e631bd77b5b3939e9a9bc","owner":"world_v2_postwar_projection_owner","securityDefiner":true,"config":["search_path=pg_catalog"],"argumentNames":["p_world","p_offset","p_limit","p_expected","status","scope","source","page","rows_text"],"strict":false,"volatility":"v","parallel":"u","result":"TABLE(status text, scope jsonb, source jsonb, page jsonb, rows_text text)","acl":[{"grantee":"world_v2_postwar_projection_owner","grantor":"world_v2_postwar_projection_owner","privilege":"EXECUTE","grantable":false},{"grantee":"world_v2_postwar_projection_reader","grantor":"world_v2_postwar_projection_owner","privilege":"EXECUTE","grantable":false}],"newBody":"\ndeclare s record;b world_v2.postwar_office_projection_document%rowtype;items jsonb;selected jsonb;version text;total integer;returned integer;begin\n if current_setting('transaction_read_only')<>'on'or current_setting('transaction_isolation')not in('repeatable read','serializable')then raise exception 'INDUSTRY_RUN_PARAMETER_STABLE_READ_ONLY_REQUIRED'using errcode='25001';end if;\n if p_offset is null or p_limit is null or p_offset<0 or p_offset>100000 or p_limit<1 or p_limit>100 or(p_offset>0 and p_expected is null)or(p_expected is not null and p_expected!~'^sha256:[a-f0-9]{64}$')then raise exception 'INDUSTRY_RUN_PARAMETER_INVALID_PAGE'using errcode='22023';end if;\n select * into s from world_v2.read_postwar_office_projection_seats(p_world)h where h.office_id='INDUSTRY';\n if not found then return query select'DENIED',null::jsonb,null::jsonb,null::jsonb,'[]';return;end if;\n select * into b from world_v2.postwar_office_projection_document d where d.world_id=p_world and d.country_id=s.country_id and d.office_id='INDUSTRY'and d.dataset='regional-source-capacity'and d.seed_id=s.seed_id and d.seed_fingerprint=s.seed_fingerprint and d.admission_ref=s.admission_ref and d.source_bundle_sha256=s.source_bundle_sha256 and not exists(select 1 from world_v2.postwar_office_projection_revocation v where v.world_id=p_world and v.document_ref=d.document_ref);\n if not found then return query select'UNAVAILABLE',null::jsonb,null::jsonb,null::jsonb,'[]';return;end if;\n items:=world_v2.postwar_industry_run_parameter_originals(p_world,s.country_id,s.seed_fingerprint,s.admission_ref);\n -- No installed source is unknown/unavailable, never a known empty facility set.\n if items is null then return query select'UNAVAILABLE',null::jsonb,null::jsonb,null::jsonb,'[]';return;end if;\n total:=jsonb_array_length(items);if total<1 or total>100 or octet_length(items::text)>48000 then raise exception 'INDUSTRY_RUN_PARAMETER_BOUNDED_SOURCE_REQUIRED'using errcode='54000';end if;\n version:='sha256:'||encode(sha256(convert_to(jsonb_build_array(p_world,s.country_id,s.seed_fingerprint,s.admission_ref,s.world_version,s.event_sequence,items)::text,'UTF8')),'hex');\n if p_expected is not null and version<>p_expected then return query select'STALE',null::jsonb,null::jsonb,null::jsonb,'[]';return;end if;\n select coalesce(jsonb_agg(x order by n),'[]'::jsonb)into selected from jsonb_array_elements(items)with ordinality q(x,n)where n>p_offset and n<=p_offset+p_limit;returned:=jsonb_array_length(selected);\n return query select case when returned=0 then'EMPTY'else'PAGE'end,\n jsonb_build_object('worldId',s.world_id,'countryId',s.country_id,'officeId',s.office_id,'authSubject',s.auth_subject,'teamId',s.team_id,'authorizationVersion',s.authorization_revision,'scopeKey',s.scope_key,'seatRef',s.seat_ref),\n jsonb_build_object('dataNature','ADMITTED_IMMUTABLE_OPENING_FACTS','sourceVersion',version,'sourceRevision','postwar-industry-run-parameters-v2','seedId',s.seed_id,'seedFingerprint',s.seed_fingerprint,'admissionRef',s.admission_ref,'modelVersion',s.model_version,'replayBinding',s.replay_binding,'sourceBundleSha256',s.source_bundle_sha256,'canonicalSeedSha256',b.canonical_seed_sha256,'worldVersion','0','eventSequence','0','originWorldVersion','0','originEventSequence','0','observedHead',jsonb_build_object('worldVersion',s.world_version,'eventSequence',s.event_sequence),'pageHash',encode(sha256(convert_to(items::text,'UTF8')),'hex'),'returnedRowsHash',encode(sha256(convert_to(selected::text,'UTF8')),'hex'),'hashAlgorithm','POSTGRES_JSONB_TEXT_UTF8_SHA256','sourcePointer',jsonb_build_object('rowOrigin','world_v2.postwar_industry_first_day_source.source_text','rowBinding','sourceRef+sourceRawSha256','adoptionContext','exact immutable World seed/admission and original site document; not a replacement row origin')),\n jsonb_build_object('offset',p_offset,'limit',p_limit,'returned',returned,'total',total,'nextOffset',case when p_offset+returned<total then p_offset+returned else null end),selected::text;\nend;"}]$all_specs$::jsonb;
spec jsonb; f record; after_row record; body text; role_name text;
begin
 foreach role_name in array array['world_v2_industry_source_owner','world_v2_postwar_projection_owner','world_v2_postwar_projection_reader']loop
  if not exists(select 1 from pg_roles where rolname=role_name and not rolcanlogin and not rolsuper and not rolbypassrls and not rolcreatedb and not rolcreaterole and not rolreplication)then raise exception 'INDUSTRY_CAPACITY_EXACT_SAFE_EXISTING_ROLE_REQUIRED'using errcode='42501';end if;
 end loop;
 -- Validate every existing target before any schema/body change.
 for spec in select value from jsonb_array_elements(specs)loop

 select p.oid,p.prosrc,p.proowner,p.proacl,p.proconfig,p.prosecdef,p.proargnames,p.proisstrict,p.provolatile,p.proparallel,p.pronargdefaults,p.proargdefaults::text defaults_source,p.proleakproof,p.prokind,(select lanname from pg_language where oid=p.prolang)language,pg_get_function_result(p.oid)result into f from pg_proc p where p.oid=to_regprocedure(spec->>'signature');
 if not found or f.pronargdefaults<>0 or f.defaults_source is not null or f.proleakproof or f.prokind<>'f'or f.language<>'plpgsql'or pg_get_userbyid(f.proowner)is distinct from spec->>'owner'or f.prosecdef is distinct from(spec->>'securityDefiner')::boolean
 or to_jsonb(f.proconfig)is distinct from spec->'config'or to_jsonb(f.proargnames)is distinct from spec->'argumentNames'
 or f.proisstrict is distinct from(spec->>'strict')::boolean or f.provolatile::text is distinct from spec->>'volatility'or f.proparallel::text is distinct from spec->>'parallel'or f.result is distinct from spec->>'result'
 or(select jsonb_agg(jsonb_build_object('grantee',case when a.grantee=0 then 'PUBLIC'else pg_get_userbyid(a.grantee)::text end,'grantor',pg_get_userbyid(a.grantor)::text,'privilege',a.privilege_type,'grantable',a.is_grantable)order by pg_get_userbyid(a.grantee)::text,pg_get_userbyid(a.grantor)::text)from aclexplode(coalesce(f.proacl,acldefault('f',f.proowner)))a)is distinct from spec->'acl'
 then raise exception 'INDUSTRY_CAPACITY_EXACT_PREDECESSOR_METADATA_REQUIRED:%',spec->>'signature'using errcode='55000';end if;
 if encode(sha256(convert_to(f.prosrc,'UTF8')),'hex')is distinct from spec->>'oldBodySha256'then raise exception 'INDUSTRY_CAPACITY_EXACT_PREDECESSOR_BODY_REQUIRED:%',spec->>'signature'using errcode='55000';end if;
 end loop;
 -- Both exact predecessor functions were checked before either replacement. Replace bodies only, preserving
 -- the actual installed defaults/signatures/OIDs/owners/ACL/search path.
 for spec in select value from jsonb_array_elements(specs)loop

 select p.oid,p.prosrc,p.proowner,p.proacl,p.proconfig,p.prosecdef,p.proargnames,p.proisstrict,p.provolatile,p.proparallel,p.pronargdefaults,p.proargdefaults::text defaults_source,p.proleakproof,p.prokind,(select lanname from pg_language where oid=p.prolang)language,pg_get_function_result(p.oid)result into f from pg_proc p where p.oid=to_regprocedure(spec->>'signature');
 if not found or f.pronargdefaults<>0 or f.defaults_source is not null or f.proleakproof or f.prokind<>'f'or f.language<>'plpgsql'or pg_get_userbyid(f.proowner)is distinct from spec->>'owner'or f.prosecdef is distinct from(spec->>'securityDefiner')::boolean
 or to_jsonb(f.proconfig)is distinct from spec->'config'or to_jsonb(f.proargnames)is distinct from spec->'argumentNames'
 or f.proisstrict is distinct from(spec->>'strict')::boolean or f.provolatile::text is distinct from spec->>'volatility'or f.proparallel::text is distinct from spec->>'parallel'or f.result is distinct from spec->>'result'
 or(select jsonb_agg(jsonb_build_object('grantee',case when a.grantee=0 then 'PUBLIC'else pg_get_userbyid(a.grantee)::text end,'grantor',pg_get_userbyid(a.grantor)::text,'privilege',a.privilege_type,'grantable',a.is_grantable)order by pg_get_userbyid(a.grantee)::text,pg_get_userbyid(a.grantor)::text)from aclexplode(coalesce(f.proacl,acldefault('f',f.proowner)))a)is distinct from spec->'acl'
 then raise exception 'INDUSTRY_CAPACITY_EXACT_PREDECESSOR_METADATA_REQUIRED:%',spec->>'signature'using errcode='55000';end if;
 if encode(sha256(convert_to(f.prosrc,'UTF8')),'hex')not in(spec->>'oldBodySha256',spec->>'newBodySha256')then raise exception 'INDUSTRY_CAPACITY_EXACT_PREDECESSOR_BODY_REQUIRED:%',spec->>'signature'using errcode='55000';end if;

  if encode(sha256(convert_to(f.prosrc,'UTF8')),'hex')=spec->>'newBodySha256'theN continue;end if;
  body:=spec->>'newBody';
  if encode(sha256(convert_to(body,'UTF8')),'hex')<>spec->>'newBodySha256'then raise exception 'INDUSTRY_CAPACITY_EXACT_TARGET_BODY_REQUIRED'using errcode='55000';end if;
  execute replace(pg_get_functiondef(f.oid),f.prosrc,body);
  select p.oid,p.prosrc,p.proowner,p.proacl,p.proconfig,p.prosecdef,p.proargnames,p.proisstrict,p.provolatile,p.proparallel,p.pronargdefaults,p.proargdefaults::text defaults_source,p.proleakproof,p.prokind,(select lanname from pg_language where oid=p.prolang)language,pg_get_function_result(p.oid)result into after_row from pg_proc p where p.oid=to_regprocedure(spec->>'signature');
  if after_row.oid is distinct from f.oid or after_row.proowner is distinct from f.proowner or after_row.proacl is distinct from f.proacl or after_row.proconfig is distinct from f.proconfig or after_row.prosecdef is distinct from f.prosecdef or after_row.proargnames is distinct from f.proargnames or after_row.proisstrict is distinct from f.proisstrict or after_row.provolatile is distinct from f.provolatile or after_row.proparallel is distinct from f.proparallel or after_row.result is distinct from f.result or after_row.pronargdefaults is distinct from f.pronargdefaults or after_row.defaults_source is distinct from f.defaults_source or after_row.proleakproof is distinct from f.proleakproof or after_row.prokind is distinct from f.prokind or after_row.language is distinct from f.language or encode(sha256(convert_to(after_row.prosrc,'UTF8')),'hex')<>spec->>'newBodySha256'then raise exception 'INDUSTRY_CAPACITY_FUNCTION_METADATA_CHANGED'using errcode='55000';end if;
 end loop;
 -- Fixed failure-injection boundary for the isolated rollback test only.
end;$industry_capacity_forward$;
commit;
